using NAudio.Wave;
using Cue = PitVoice.Core.Cues.Cue;

namespace PitVoice.Speech.Cues;

/// <summary>A decoded cue: mono float samples at the file's rate.</summary>
internal sealed record CueSound(float[] Samples, int SampleRate)
{
    public TimeSpan Duration => TimeSpan.FromTicks(Samples.LongLength * TimeSpan.TicksPerSecond / SampleRate);
}

/// <summary>
/// The built-in cue sounds (design decision 2): WAV files generated by <c>tools/cue-gen</c> and embedded in this
/// assembly. Decoding and rendering for an output device are platform-independent, so they are tested on every OS.
/// </summary>
internal static class CueSounds
{
    public static string ResourceName(Cue cue) => $"PitVoice.Speech.Cues.{cue.ToString().ToLowerInvariant()}.wav";

    /// <summary>Reads and decodes the embedded sound; throws <see cref="InvalidDataException"/> when it is missing or broken.</summary>
    public static CueSound Load(Cue cue)
    {
        var name = ResourceName(cue);
        using var stream = typeof(CueSounds).Assembly.GetManifestResourceStream(name)
            ?? throw new InvalidDataException($"embedded sound {name} is missing");
        return Decode(stream, name);
    }

    public static CueSound Decode(Stream wav, string name)
    {
        try
        {
            using var reader = new WaveFileReader(wav);
            var provider = reader.ToSampleProvider();
            var channels = provider.WaveFormat.Channels;
            var interleaved = new List<float>();
            var chunk = new float[provider.WaveFormat.SampleRate * channels];
            int read;
            while ((read = provider.Read(chunk)) > 0)
            {
                interleaved.AddRange(chunk.AsSpan(0, read));
            }

            var mono = new float[interleaved.Count / channels];
            for (var frame = 0; frame < mono.Length; frame++)
            {
                var sum = 0f;
                for (var channel = 0; channel < channels; channel++)
                {
                    sum += interleaved[(frame * channels) + channel];
                }

                mono[frame] = sum / channels;
            }

            if (mono.Length == 0)
            {
                throw new InvalidDataException($"sound {name} has no samples");
            }

            return new CueSound(mono, provider.WaveFormat.SampleRate);
        }
        catch (Exception e) when (e is FormatException or EndOfStreamException or ArgumentException or NotSupportedException)
        {
            throw new InvalidDataException($"sound {name} could not be decoded: {e.Message}", e);
        }
    }

    /// <summary>Linear gain of a volume in percent; clamped to 0..100.</summary>
    public static float Gain(int volume) => Math.Clamp(volume, 0, 100) / 100f;

    /// <summary>
    /// Interleaved float samples for an output of <paramref name="sampleRate"/> and <paramref name="channels"/>:
    /// resampled linearly (the cues are plain tones) and scaled by <paramref name="volume"/>.
    /// </summary>
    public static float[] Render(CueSound sound, int volume, int sampleRate, int channels)
    {
        ArgumentNullException.ThrowIfNull(sound);
        ArgumentOutOfRangeException.ThrowIfNegativeOrZero(sampleRate);
        ArgumentOutOfRangeException.ThrowIfNegativeOrZero(channels);

        var gain = Gain(volume);
        var frames = (int)((long)sound.Samples.Length * sampleRate / sound.SampleRate);
        var output = new float[frames * channels];
        var step = (double)sound.SampleRate / sampleRate;
        for (var frame = 0; frame < frames; frame++)
        {
            var position = frame * step;
            var index = (int)position;
            var fraction = (float)(position - index);
            var a = sound.Samples[Math.Min(index, sound.Samples.Length - 1)];
            var b = sound.Samples[Math.Min(index + 1, sound.Samples.Length - 1)];
            var value = (a + ((b - a) * fraction)) * gain;
            for (var channel = 0; channel < channels; channel++)
            {
                output[(frame * channels) + channel] = value;
            }
        }

        return output;
    }
}
